        thread_count[7]) );
  DFFX1_HVT device_conrol_register_reg_6_ ( .D(N10), .CLK(net7881), .Q(
        thread_count[6]) );
  DFFX1_HVT device_conrol_register_reg_5_ ( .D(N9), .CLK(net7881), .Q(
        thread_count[5]) );
  AND2X1_HVT U13 ( .A1(n3), .A2(device_control_data[7]), .Y(N11) );
  AND2X1_HVT U12 ( .A1(n3), .A2(device_control_data[6]), .Y(N10) );
