  AND2X1_HVT U6 ( .A1(n3), .A2(device_control_data[0]), .Y(N4) );
  AND2X1_HVT U5 ( .A1(device_control_write_enable), .A2(n2), .Y(n3) );
  DFFX1_HVT device_conrol_register_reg_4_ ( .D(N8), .CLK(net7881), .Q(
        thread_count[4]) );
  INVX1_HVT U4 ( .A(reset), .Y(n2) );
